"""Algorithm A: the commutator-invariance pinning test.

Decides, for a finite group G given by a list of permutations and a binary
fork Y on G, whether ANY congruence condition can determine Y -- without
searching over moduli.  The criterion is: Y is pinned by some abelian
character iff Y(g c) = Y(g) for every g in G and every commutator c.
"""

from __future__ import annotations

import itertools
from typing import Callable, List, Optional, Sequence, Tuple

Perm = Tuple[int, ...]


def compose(a: Perm, b: Perm) -> Perm:
    return tuple(a[b[i]] for i in range(len(a)))


def inverse(a: Perm) -> Perm:
    out = [0] * len(a)
    for i, ai in enumerate(a):
        out[ai] = i
    return tuple(out)


def commutator_subgroup(group: Sequence[Perm]) -> List[Perm]:
    """[G,G] as the subgroup generated by all commutators g h g^-1 h^-1."""
    gens = {compose(compose(g, h), compose(inverse(g), inverse(h)))
            for g in group for h in group}
    identity = tuple(range(len(group[0])))
    closure = {identity}
    stack = [identity]
    while stack:
        x = stack.pop()
        for s in gens:
            y = compose(x, s)
            if y not in closure:
                closure.add(y)
                stack.append(y)
    return sorted(closure)


def pinning_test(group: Sequence[Perm],
                 fork: Callable[[Perm], bool]
                 ) -> Tuple[bool, Optional[Tuple[Perm, Perm]], int, int]:
    """Return (pinnable, witness, |[G,G]|, |G^ab|).

    'pinnable' is True iff some abelian character of G determines the fork;
    on failure 'witness' is a pair (g, c) with c a commutator and
    Y(g c) != Y(g), which certifies that NO modulus can ever work.
    """
    comm = commutator_subgroup(group)
    for g in group:
        for c in comm:
            if fork(compose(g, c)) != fork(g):
                return False, (g, c), len(comm), len(group) // len(comm)
    return True, None, len(comm), len(group) // len(comm)


def demo() -> None:
    s4: List[Perm] = [tuple(p) for p in itertools.permutations(range(4))]
    c3: List[Perm] = [(0, 1, 2), (1, 2, 0), (2, 0, 1)]

    for name, group, fork_name, fork in [
        ("C3", c3, "splits completely", lambda g: g == (0, 1, 2)),
        ("S4", s4, "has a root", lambda g: any(g[i] == i for i in range(4))),
        ("S4", s4, "sign is +1", lambda g: sign(g) == 1),
    ]:
        ok, witness, ncomm, nab = pinning_test(group, fork)
        print(f"{name:3s}  fork '{fork_name:20s}'  |[G,G]| = {ncomm:2d}  |G^ab| = {nab:2d}  "
              f"pinnable = {ok}" + ("" if ok else f"  witness = {witness}"))


def sign(a: Perm) -> int:
    seen = [False] * len(a)
    parity = 0
    for i in range(len(a)):
        if not seen[i]:
            j, length = i, 0
            while not seen[j]:
                seen[j] = True
                j = a[j]
                length += 1
            parity += length - 1
    return 1 if parity % 2 == 0 else -1


if __name__ == "__main__":
    demo()
